DROP TABLE IF EXISTS `leave_balances`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `leave_balances` (
  `id` int NOT NULL AUTO_INCREMENT,
  `signup_id` int NOT NULL,
  `privilege_leave_balance` float NOT NULL,
  `casual_leave_balance` float NOT NULL,
  `last_updated` date DEFAULT NULL,
  `compensatory_leave_balance` float NOT NULL,
  `admin_id` int DEFAULT NULL,
  `total_privilege_leave` double NOT NULL DEFAULT '0',
  `total_casual_leave` double NOT NULL DEFAULT '0',
  `total_compensatory_leave` double NOT NULL DEFAULT '0',
  `used_privilege_leave` double NOT NULL DEFAULT '0',
  `used_casual_leave` double NOT NULL DEFAULT '0',
  `used_comp_leave` double NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `signup_id` (`signup_id`),
  CONSTRAINT `leave_balances_ibfk_1` FOREIGN KEY (`signup_id`) REFERENCES `signups` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=170 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
