INSERT INTO `news_feeds` VALUES (1,'Holiday','sdsszd',NULL,'NHQ','All','2025-05-16 04:29:51'),(2,'Revision of Notice Period Policy for Deputed Employees','Dear Team,\r\n\r\nThis is to inform you that as per the terms of your appointment letter, the current notice period stands at 90 days. However, after reviewing the existing policy, the management has decided to revise the notice period for all employees deputed at client locations.\r\n\r\nEffective 1st November 2025, the notice period will be 30 days for all deputed employees.\r\n\r\nWe request you to kindly take note of this change. All other terms and conditions of employment will remain unchanged.\r\n\r\nFor any clarification, please feel free to connect with the HR team.',NULL,'Bangalore-Xray','Engineering','2025-11-06 11:33:42'),(3,'Revision of Notice Period Policy for Deputed Employees','Dear Team,\r\n\r\nThis is to inform you that as per the terms of your appointment letter, the current notice period stands at 90 days. However, after reviewing the existing policy, the management has decided to revise the notice period for all employees deputed at client locations.\r\n\r\nEffective 1st November 2025, the notice period will be 30 days for all deputed employees.\r\n\r\nWe request you to kindly take note of this change. All other terms and conditions of employment will remain unchanged.\r\n\r\nFor any clarification, please feel free to connect with the HR team.',NULL,'Gurugram-Awesome','Engineering','2025-11-06 11:34:29'),(4,'Revision of Notice Period Policy for Deputed Employees','Dear Team,\r\n\r\nThis is to inform you that as per the terms of your appointment letter, the current notice period stands at 90 days. However, after reviewing the existing policy, the management has decided to revise the notice period for all employees deputed at client locations.\r\n\r\nEffective 1st November 2025, the notice period will be 30 days for all deputed employees.\r\n\r\nWe request you to kindly take note of this change. All other terms and conditions of employment will remain unchanged.\r\n\r\nFor any clarification, please feel free to connect with the HR team.',NULL,'Gurugram-Rabbit','Engineering','2025-11-06 11:34:59'),(5,'Revision of Notice Period Policy for Deputed Employees','Dear Team,\r\n\r\nThis is to inform you that as per the terms of your appointment letter, the current notice period stands at 90 days. However, after reviewing the existing policy, the management has decided to revise the notice period for all employees deputed at client locations.\r\n\r\nEffective 1st November 2025, the notice period will be 30 days for all deputed employees.\r\n\r\nWe request you to kindly take note of this change. All other terms and conditions of employment will remain unchanged.\r\n\r\nFor any clarification, please feel free to connect with the HR team.',NULL,'Jaipur-Rabbit','Engineering','2025-11-06 11:35:48'),(6,'Revision of Notice Period Policy for Deputed Employees','Dear Team,\r\n\r\nThis is to inform you that as per the terms of your appointment letter, the current notice period stands at 90 days. However, after reviewing the existing policy, the management has decided to revise the notice period for all employees deputed at client locations.\r\n\r\nEffective 1st November 2025, the notice period will be 30 days for all deputed employees.\r\n\r\nWe request you to kindly take note of this change. All other terms and conditions of employment will remain unchanged.\r\n\r\nFor any clarification, please feel free to connect with the HR team.',NULL,'G.Noida-Rabbit','Engineering','2025-11-06 11:36:23'),(7,'Revision of Notice Period Policy for Deputed Employees','Dear Team,\r\n\r\nThis is to inform you that as per the terms of your appointment letter, the current notice period stands at 90 days. However, after reviewing the existing policy, the management has decided to revise the notice period for all employees deputed at client locations.\r\n\r\nEffective 1st November 2025, the notice period will be 30 days for all deputed employees.\r\n\r\nWe request you to kindly take note of this change. All other terms and conditions of employment will remain unchanged.\r\n\r\nFor any clarification, please feel free to connect with the HR team.',NULL,'Mumbai-Rabbit','Engineering','2025-11-06 11:37:21'),(8,'Revision of Notice Period Policy for Deputed Employees','Dear Team,\r\n\r\nThis is to inform you that as per the terms of your appointment letter, the current notice period stands at 90 days. However, after reviewing the existing policy, the management has decided to revise the notice period for all employees deputed at client locations.\r\n\r\nEffective 1st November 2025, the notice period will be 30 days for all deputed employees.\r\n\r\nWe request you to kindly take note of this change. All other terms and conditions of employment will remain unchanged.\r\n\r\nFor any clarification, please feel free to connect with the HR team.',NULL,'Kolkata-Rabbit','Engineering','2025-11-06 11:38:00'),(9,'Reg. Notification of Leave Policy Updates_Effective November 2025','Dear Team,\r\nThis notice is to formally communicate the updates made to our leave policies, effective November 2025:\r\n1. Sandwich Leave Policy\r\nThe sandwich leave policy will no longer be applicable.\r\n2. Leaves During Probation\r\nLeaves availed during the probation period will be processed as per the standard leave policy. No salary deduction will be applied for approved leaves. Employees may avail monthly paid leaves based on the availability of their leave balance.\r\n\r\nAll employees are requested to comply with these updated guidelines. \r\n\r\nFor any further clarification, please contact the HR Department.',NULL,'Bangalore-Xray','Engineering','2025-12-10 16:48:54'),(10,'HOLIDAY LIST 2026','Dear Team,\r\n\r\nPlease find HOLIDAY LIST FOR THE YEAR 2026','HOLIDAY_LIST_FOR_THE_YEAR_2026.pdf','NHQ','Engineering','2025-12-23 13:53:34'),(11,'HOLIDAY LIST FOR THE YEAR 2026','Dear Team,\r\n\r\nPlease find HOLIDAY LIST FOR THE YEAR 2026','HOLIDAY_LIST_FOR_THE_YEAR_2026.pdf','NHQ','Software Development','2025-12-23 13:54:12'),(12,'HOLIDAY LIST FOR THE YEAR 2026','Dear Team,\r\n\r\nPlease find HOLIDAY LIST FOR THE YEAR 2026','HOLIDAY_LIST_FOR_THE_YEAR_2026.pdf','NHQ','Accounts','2025-12-23 13:54:46'),(13,'HOLIDAY LIST FOR THE YEAR 2026','Dear Team,\r\n\r\nPlease find HOLIDAY LIST FOR THE YEAR 2026','HOLIDAY_LIST_FOR_THE_YEAR_2026.pdf','NHQ','Accounts','2025-12-23 13:55:16'),(14,'HOLIDAY LIST FOR THE YEAR 2026','Dear Team,\r\n\r\nPlease find HOLIDAY LIST FOR THE YEAR 2026','HOLIDAY_LIST_FOR_THE_YEAR_2026.pdf','NHQ','Human Resource','2025-12-23 13:56:23');
