INSERT INTO `queries` VALUES (2,28,'unable to punch in and punchout at client office location','IT Department','unable to punch in and punchout at client office location.\r\n\r\nerror found: you are not near any authorized location and \"work from home\" is not selected. same error found in android mobile and window laptop.\r\n\r\nkindly check and confirm.','2025-06-30 15:24:19','Open',NULL,'IT Department'),(8,89,'Payslip query','Accounts','Could you please tell us when our UAN number will be added in the payslip ','2025-11-12 16:52:56','Open',NULL,'Accounts'),(9,53,'January month CL not available in portal ','Human Resource','While trying to apply for CL in the month of January, when no CL balance was available, I received a notification asking me to apply for PL instead. However, after applying for PL, the system created duplicate (two) applications for the same day.','2026-02-03 12:49:08','Open','Screenshot_20260119_093601.jpg','Human Resource'),(10,19,'Salary Slip ','Human Resource, Accounts','October and November month salary slip attached incorrect ','2026-02-03 12:51:22','Open',NULL,'Human Resource, Accounts');
